fn thrown(e:Box<dyn std::any::Any+Send>)->String{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");for n in ["NullPointerException","IllegalStateException","ArrayIndexOutOfBoundsException","IndexOutOfBoundsException","RuntimeException"]{if s.starts_with(n){return n.into();}}if s=="Ptg array size mismatch"{return "RuntimeException".into();}format!("unexpected Rust panic: {s}")}
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>json!({"result":thrown(e)})}}
fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
fn unhex(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
