fn names(input:&Value)->Value{json!(input["names"].as_array().unwrap().iter().map(|p|{let sv=if p["version"]==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007};let mut n=if let Some(b)=p["builtin"].as_i64(){NameRecord::NameRecord__builtin(b as i8,p["sheet"].as_i64().unwrap()as i32,sv)}else{NameRecord::NameRecord(sv)};n.setOptionFlag(p["flags"].as_i64().unwrap()as i16);n.setKeyboardShortcut(p["keyboard"].as_i64().unwrap()as i8);let made=call(||{n.setNameText__nullable(p["name"].as_str());Value::Null});n.setSheetNumber(p["sheet"].as_i64().unwrap()as i32);n.setCustomMenuText(p["menu"].as_str().map(str::to_string));n.setDescriptionText(p["description"].as_str().map(str::to_string));n.setHelpTopicText(p["help"].as_str().map(str::to_string));n.setStatusBarText(p["status"].as_str().map(str::to_string));let bytes=unhex(p["ptgs"].as_str().unwrap());let ps=array(Ptg::readTokens(bytes.len()as i32,&bytes,sv));n.setNameDefinition(ps.clone());let before=name(&mut n);let sameInput=Rc::ptr_eq(&ps,&n.getNameDefinition());let sameReturned=Rc::ptr_eq(&n.getNameDefinition(),&n.getNameDefinition());let mut copy=n.copy();let cp=name(&mut copy);json!({"made":made,"before":before,"sameInput":sameInput,"sameReturned":sameReturned,"copy":cp,"copyArrayDistinct":!Rc::ptr_eq(&copy.getNameDefinition(),&n.getNameDefinition()),"copyFormulaDistinct":!Rc::ptr_eq(&copy.getFormula().unwrap(),&n.getFormula().unwrap()),"copyBytesDistinct":!Rc::ptr_eq(&copy.getFormula().unwrap().borrow().getByteEncoding().unwrap(),&n.getFormula().unwrap().borrow().getByteEncoding().unwrap())})}).collect::<Vec<_>>())}
fn aliases(book:&Rc<KmoBook>)->Value{let n:NameRecordRef=Rc::new(RefCell::new(NameRecord::NameRecord(SpreadsheetVersion::EXCEL2007)));n.borrow_mut().setNameText("before");let ps=array(vec![int(3)]);n.borrow_mut().setNameDefinition(ps.clone());let e=EvaluationName::EvaluationName(Some(n.clone()),4);let index=book.getLinkTable().borrow().getNumNames();book.getLinkTable().borrow_mut().addName(n.clone());let mut o=json!({"sameTable":Rc::ptr_eq(&book.getLinkTable().borrow().getNameRecord(index).unwrap(),&n)});n.borrow_mut().setNameText(" changed ");n.borrow_mut().setSheetNumber(9);n.borrow_mut().setHidden(true);o["heldName"]=json!(e.getNameText());o["heldSheet"]=json!(e.getSheetIndexOneBased());o["heldFormula"]=tokens(&e.getNameDefinition());ps.borrow_mut()[0]=Some(crate::cn::wps::et::ss::formula::ptg::Ptg::ptgRef(int(99)));o["mutatedCache"]=name(&mut n.borrow_mut());let f=Rc::new(RefCell::new(Formula::create(&[int(333)],SpreadsheetVersion::EXCEL97)));n.borrow_mut().setFormula(Some(f.clone()));o["sameFormula"]=json!(Rc::ptr_eq(&n.borrow().getFormula().unwrap(),&f));o["afterSetFormula"]=name(&mut n.borrow_mut());o["copyAfterSetFormula"]=name(&mut n.borrow().copy());n.borrow_mut().setNameDefinition__array(None);o["afterNullDefinition"]=name(&mut n.borrow_mut());n.borrow_mut().setFormula(None);o["nullHas"]=call(||n.borrow().hasFormula());o["cachedWhileNull"]=call(||tokens(&n.borrow_mut().getNameDefinition()));n.borrow_mut().setNameDefinition__array(None);n.borrow_mut().setFormula(None);o["recovered"]=call(||tokens(&n.borrow_mut().getNameDefinition()));o["afterRecovery"]=name(&mut n.borrow_mut());o}
fn formulas(input:&Value)->Value{json!(input["formulas"].as_array().unwrap().iter().map(|p|{let b=p["bytes"].as_str().map(|s|Rc::new(RefCell::new(unhex(s).into_boxed_slice())));let f=Formula::Formula(b.clone(),p["encoded"].as_i64().unwrap()as i32,Some(SpreadsheetVersion::EXCEL97));let mut o=json!({"before":formula(&f),"sameInput":match(&b,f.getByteEncoding()){(None,None)=>true,(Some(a),Some(b))=>Rc::ptr_eq(a,&b),_=>false},"hash":call(||f.hashCode()),"equalsSelf":call(||f.equals(Some(&f))),"equalsNull":f.equals(None),"equalsOther":f.equals(Some(&"x"))});let mut out=LittleEndianByteArrayOutput::new();let mut serialized=call(||{f.serialize(&mut out);Value::Null});serialized["bytes"]=json!(hex(&out.get_bytes()));o["serialize"]=serialized;o["copy"]=call(||formula(&f.copy()));if let Some(b)=b{if !b.borrow().is_empty(){let last=b.borrow().len()-1;b.borrow_mut()[last]^=1;o["afterInputMutation"]=formula(&f);}}o}).collect::<Vec<_>>())}
