fn original_android_names_formula_and_reference_history(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/name-records-r0b46");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let j:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let actual=json!({"flags":flags(),"names":names(&input),"aliases":aliases(&book),"formulas":formulas(&input)});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&actual,&j,"root");}
